INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1f7fc9e6f429b842cd178ab26b4a749a', 'JEEAdvanced', '12', 'Mathematics', 'math_12_calculus_advanced', 'Calculus', 'Improper integrals convergence', '["math_12_integrals"]', '["improper integral","convergence","p-integral"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'The improper integral $\int_1^\infty \frac{1}{x^p} \, dx$ converges if and only if:', '["p > 0", "p > 1", "p < 1", "p < 0"]', 'p > 1', 'For $\int_1^\infty x^{-p} dx$, convergence occurs when p > 1 by p-integral test.', '["Step 1: Recall p-integral convergence condition", "Step 2: Apply to given integral"]', '\int_1^\infty x^{-p} dx \text{ converges iff } p>1', 'math.calculus.improper_integral_p_test', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:23:44.467Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1f804bd2b1dc04a90bf0450a07d3139c', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_kinetics_half_life', 'Chemical Kinetics', 'Half life calculations', '[]', '["first‑order kinetics","half‑life","rate constant","exponential decay"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A first‑order reaction $A \rightarrow products$ has a rate constant $k = 2.0\times10^{-3}\,\text{s}^{-1}$. What is the half‑life of the reaction?', '["173 s", "346 s", "693 s", "1386 s"]', '346 s', 'For a first‑order reaction, $t_{1/2}=\frac{0.693}{k}=\frac{0.693}{2.0\times10^{-3}}\,\text{s}=346.5\,\text{s}\approx346\,\text{s}$.', '["Step 1: Recall the half‑life formula for a first‑order reaction $t_{1/2}=\\frac{0.693}{k}$.", "Step 2: Substitute $k = 2.0\\times10^{-3}\\,\\text{s}^{-1}$ into the formula.", "Step 3: Compute $t_{1/2}=0.693/(2.0\\times10^{-3})=346.5\\,\\text{s}$.", "Step 4: Round to the nearest whole number: $t_{1/2}\\approx346\\,\\text{s}$."]', 't_{1/2}=0.693/k', 'chemistry.kinetics.half_life', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:17.374Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1f85f3fb252c2da31b910fc10d0fd7e4', 'JEEAdvanced', '12', 'Physics', 'phy_12_jm_advanced_mechanics', 'Advanced Mechanics', 'Compound Physical Pendulum', '[]', '["compound_pendulum","moment_of_inertia","centre_of_mass","small_oscillations","period_formula"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'A compound pendulum consists of two point masses $m_1$ and $m_2$ attached to a light rod of length $L$, with $m_1$ at a distance $a$ from the pivot and $m_2$ at a distance $b$ from the pivot (so $a+b=L$). Which of the following expressions correctly give the period $T$ of small oscillations? (Assume $I$ is the total moment of inertia about the pivot, $M=m_1+m_2$, $g$ is the acceleration due to gravity, and $d$ is the distance of the centre of mass from the pivot.)', '["$T = 2\\pi \\sqrt{\\frac{I}{M g d}},\\ \\text{where } d = \\frac{m_1 a + m_2 b}{M}$", "$T = 2\\pi \\sqrt{\\frac{m_1 a^2 + m_2 b^2}{M g \\frac{m_1 a + m_2 b}{M}}}$", "$T = 2\\pi \\sqrt{\\frac{I}{M g L}}$", "$T = 2\\pi \\sqrt{\\frac{I}{M g \\frac{ab}{L}}}$"]', '["[\"$T = 2\\PI \\SQRT{\\FRAC{I}{M G D}},\\ \\TEXT{WHERE } D = \\FRAC{M_1 A + M_2 B}{M}$\",\"$T = 2\\PI \\SQRT{\\FRAC{M_1 A^2 + M_2 B^2}{M G \\FRAC{M_1 A + M_2 B}{M}}}$\"]"]', 'For a compound pendulum the period is $T=2\pi\sqrt{I/(Mgd)}$, where $d$ is the centre‑of‑mass distance from the pivot. Substituting $I=m_1 a^2+m_2 b^2$ and $d=(m_1 a+m_2 b)/M$ yields the two equivalent correct forms shown in options A and B. Options C and D use incorrect characteristic lengths.', '["Step 1: Write the general period formula $T=2\\pi\\sqrt{I/(Mgd)}$.", "Step 2: Compute the centre‑of‑mass distance $d=\\frac{m_1 a+m_2 b}{M}$.", "Step 3: Express the moment of inertia $I=m_1 a^2+m_2 b^2$ for point masses.", "Step 4: Substitute $I$ and $d$ into the period formula to obtain the two correct expressions.", "Step 5: Identify the incorrect options that replace $d$ with $L$ or $ab/L$."]', 'T = 2\pi \sqrt{\frac{I}{M g d}}', 'physics.mechanics.compound_pendulum_period', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:09.333Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1f886f33c72e091ec15c62a7f52be4f2', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electromagnetic Induction', 'Eddy currents and transformer losses', '["phy_12_jm_ac_circuits"]', '["transformer efficiency","eddy current loss","power loss calculation","AC circuits","electromagnetic induction","energy conservation in transformers"]', 1, 0, '["NEET"]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'A transformer has an efficiency of 90% and is used to step down the voltage from 2000 V to 200 V. If the input power is 4.5 kW, what is the power loss due to eddy currents and other losses in the transformer? $$\text{(Assume no hysteresis or resistive losses separately given)}$$', '[]', '450', 'Input power is given as 4.5 kW = 4500 W. Efficiency = 90%, so output power = 0.9 × 4500 = 4050 W. Therefore, power loss = Input - Output = 4500 - 4050 = 450 W. This loss includes eddy current losses and other unaccounted losses in the transformer core.', '["Step 1: Identify input power: 4.5 kW = 4500 W", "Step 2: Calculate output power using efficiency: 0.9 × 4500 = 4050 W", "Step 3: Compute power loss: 4500 - 4050 = 450 W"]', 'Efficiency = (Output Power / Input Power) Ã— 100%', 'physics.emi.transformer_efficiency_misinterpretation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:26.387Z', 1);
