INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('221944b4f1f3f37c16c3afb7673cf33f', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial_theorem', 'Binomial Theorem', 'Binomial expansion (x+y)^n general term', '[]', '["general term in binomial expansion","independent term","exponent manipulation","combinatorics","coefficient extraction","negative base","power of variable"]', 0, 0, '[]', 'Integer', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 5, 0.0, 'In the binomial expansion of $ (2x - \frac{1}{x})^6 $, what is the coefficient of the term independent of $ x $?', '[]', '-160', 'General term: $ T_{r+1} = \binom{6}{r} (2x)^{6-r} \left(-\frac{1}{x}\right)^r = \binom{6}{r} 2^{6-r} (-1)^r x^{6-2r} $. For independence from $ x $, $ 6 - 2r = 0 \Rightarrow r = 3 $. Then coefficient is $ \binom{6}{3} \cdot 2^3 \cdot (-1)^3 = 20 \cdot 8 \cdot (-1) = -160 $.', '["Step 1: Write general term $ T_{r+1} = \\binom{n}{r} a^{n-r} b^r $", "Step 2: Identify $ a = 2x $, $ b = -1/x $, $ n = 6 $", "Step 3: Combine powers: $ x^{6-r} \\cdot x^{-r} = x^{6-2r} $", "Step 4: Set exponent zero: $ 6 - 2r = 0 \\Rightarrow r = 3 $", "Step 5: Plug into coefficient: $ \\binom{6}{3} \\cdot 2^3 \\cdot (-1)^3 = -160 $"]', '$ T_{r+1} = \binom{n}{r} a^{n-r} b^r $', 'math.binomial.independent_term_exponent_mistake', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:52.468Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('221a25c60419160e129e74a27b7f4a30', 'Board', '10', 'Science', 'bio_10_board_control_coordination', 'Control and Coordination', 'Insulin glucagon diabetes', '[]', '["hormones","glucagon","insulin","diabetes","blood glucose","liver","glycogen"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 2, 0.0, 'Which hormone regulates blood glucose by converting glycogen to glucose in the liver during hypoglycemia?', '["Insulin", "Glucagon", "Thyroxine", "Adrenaline"]', 'Glucagon', 'Glucagon is released when blood glucose is low and stimulates glycogen breakdown.', '["Step 1: Identify hormone for low blood sugar", "Step 2: Glucagon promotes glycogenolysis"]', '', 'biology.hormones.glucagon_insulin_confusion', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_control', '2026-05-22T15:06:07.072Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('221e2110343b7e7aca16120f370bcf81', 'Board', '10', 'Science', 'sci_10_board_light_dispersion', 'Light', 'Dispersion of white light', '[]', '["dispersion","prism","white light","refraction","wavelength dependence","spectrum"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 2, 0.0, 'When a narrow beam of white light passes through a triangular prism, the emerging light spreads into a spectrum of colors. Which phenomenon primarily causes this dispersion?', '["Refraction due to wavelength‑dependent speed of light in glass.", "Reflection at the prism surfaces.", "Diffraction around the prism edges.", "Polarization of light by the prism material."]', 'Refraction due to wavelength‑dependent speed of light in glass.', 'Different wavelengths travel at slightly different speeds in glass, so each color is refracted by a different amount according to Snell''s law. This separation of colors produces the observed spectrum.', '["Step 1: Recall that the speed of light in a medium depends on wavelength (dispersion).", "Step 2: Apply Snell''s law to see that each wavelength bends by a different angle.", "Step 3: Recognise that the angular separation creates the visible spectrum."]', '', 'science.light.dispersion_refraction', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:34.313Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('22245d7bc2c25aaa61f3c6d8440f0aeb', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'phy_12_jm_ray_optics', 'Ray Optics and Optical Instruments', '[]', '["Prism","Deviation of Light","Angle of Deviation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2050, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A prism of angle $A$ is placed in a beam of light. The deviation of light through the prism is given by $\delta = (A - \sin A)\,\text{radians}$. If the angle of deviation is $\delta = 30^\circ$, find the value of $A$ in degrees.', '["$A = 30^\\circ$", "$A = 45^\\circ$", "$A = 60^\\circ$", "$A = 90^\\circ$"]', '$A = 60^\circ$', 'Step 1: Recall the formula for the deviation of light through a prism, which is given by $\delta = (A - \sin A)\,\text{radians}$. Step 2: Substitute the given value of $\delta$ into the formula: $30^\circ = (A - \sin A)\,\text{radians}$. Step 3: Solve for $A$ by rearranging the equation and using a calculator to find the value of $A$ in degrees.', '["Step 1: Recall the formula for the deviation of light through a prism, which is given by $\\delta = (A - \\sin A)\\,\\text{radians}$.", "Step 2: Substitute the given value of $\\delta$ into the formula: $30^\\circ = (A - \\sin A)\\,\\text{radians}$.", "Step 3: Solve for $A$ by rearranging the equation and using a calculator to find the value of $A$ in degrees."]', '\delta = (A - \sin A)\,\text{radians}', 'physics.optics.prism_deviation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_MAINS_EASY->JEE_MAINS_MEDIUM) based on ELO score 2050 and target exam JEEMains', '2026-05-22T13:54:40.554Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('222b33c922376fb9e586a40b9be29851', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Gametogenesis comparison male female', '[]', '["gametogenesis","spermatogenesis","oogenesis","meiosis"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 1, -1.0, 'Which statement is INCORRECT regarding gametogenesis in humans?', '["Spermatogenesis is continuous", "Oogenesis starts in embryonic stage", "Spermatogenesis yields 4 haploid cells", "Oogenesis yields 4 functional ova"]', 'Oogenesis yields 4 functional ova', 'Oogenesis involves unequal cytoplasmic division yielding one functional ovum.', '["Spermatogenesis produces 4 functional sperms", "Oogenesis produces 1 ovum and 3 polar bodies"]', '', 'biology.reproduction.gametogenesis_yield', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:13:33.744Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2233016053f414ea68c1a2dc34926d9f', 'Board', '9', 'Mathematics', 'math_9_board_algebra', 'Algebraic Expressions', 'Factorisation identities (a+b)² a²-b²', '[]', '["factorisation","algebraic identities","difference of squares","polynomials","quadratic expression"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1150, 'CLASS_9_BASIC', 2, 0.0, 'Factorise: $x^2 - 9$. Which identity is used?', '["$(x+3)^2$", "$(x-3)^2$", "$(x+3)(x-3)$", "$x(x-9)$"]', '$(x+3)(x-3)$', 'Uses identity $a^2 - b^2 = (a+b)(a-b)$; here $x^2 - 3^2$.', '["Step 1: Recognize difference of squares.", "Step 2: Apply $a^2 - b^2 = (a+b)(a-b)$."]', 'a^2 - b^2 = (a + b)(a - b)', 'math.algebra.identity_confusion', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1150 and target exam Board', '2026-05-22T15:04:59.452Z', 1);
